.twyne-math-source-editor {
  display: flex;
  min-width: min(28rem, 80vw);
  flex-direction: column;
  gap: 0.5rem;
  padding: 0.65rem;
  border: 1px solid currentColor;
  border-radius: 0.4rem;
  background: Canvas;
  color: CanvasText;
  text-align: left;
}

.twyne-math-inline .twyne-math-source-editor {
  display: inline-flex;
  min-width: min(22rem, 70vw);
  vertical-align: middle;
}

.twyne-math-source-label {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  font-size: 0.8rem;
  font-weight: 600;
}

.twyne-math-source-input {
  width: 100%;
  resize: vertical;
  border: 1px solid color-mix(in srgb, currentColor 35%, transparent);
  border-radius: 0.25rem;
  padding: 0.5rem;
  background: Canvas;
  color: CanvasText;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.875rem;
  font-weight: 400;
  line-height: 1.4;
}

.twyne-math-source-input:focus-visible,
.twyne-math-source-save:focus-visible,
.twyne-math-source-cancel:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}

.twyne-math-source-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.4rem;
}

.twyne-math-source-save,
.twyne-math-source-cancel {
  min-height: 2rem;
  border: 1px solid currentColor;
  border-radius: 0.25rem;
  padding-inline: 0.65rem;
  background: Canvas;
  color: CanvasText;
  font: inherit;
  cursor: pointer;
}

.twyne-math-source-save {
  background: CanvasText;
  color: Canvas;
}

/* Live preview inside the LaTeX source editor: same KaTeX output the
   NodeView renders after save, so the writer sees the equation while typing.
   Purely presentational — saving still goes through the form submit. */
.twyne-math-source-preview {
  overflow: auto;
  max-height: 12rem;
  border: 1px solid color-mix(in srgb, currentColor 35%, transparent);
  border-radius: 0.25rem;
  padding: 0.5rem 0.65rem;
  background: Canvas;
  color: CanvasText;
  font-size: 0.95rem;
  text-align: center;
}

.twyne-math-source-preview-hint {
  color: color-mix(in srgb, currentColor 60%, transparent);
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.8rem;
}

.twyne-math-source-preview-output {
  display: inline-block;
  max-width: 100%;
}

.twyne-math-source-preview-error {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.4rem;
  border-color: #a84632;
  background: #fff2ee;
  color: #742718;
  text-align: left;
}

.twyne-math-source-preview-message {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.8rem;
  overflow-wrap: anywhere;
}
